        gravity: 0.03,
        drag: 0.94,
        life: randInt(16, 28),
        maxLife: 28,
        size: rand(1, 3),
        color,
        layer: 0,
      });
    }
  }

  function spawnLeaf(x, y) {
    particles.push({
      type: 'leaf',
      x,
      y,
      vx: rand(-0.5, 0.5),
      vy: rand(-0.3, 0.2),
      gravity: 0.02,
      drag: 0.99,
      life: randInt(50, 90),
      maxLife: 90,
      size: rand(2, 4),
      color: Math.random() < 0.5 ? '#8eab59' : '#c47b57',
      layer: 1,
      spin: rand(-0.1, 0.1),
      rot: rand(0, 6.28),
    });
  }

  function physics(f, drag = 1) {
    const wasGround = f.onGround;
    f.x += f.vx;
    f.y += f.vy;
    f.vy += 0.55;
    if (f.vy > 13) f.vy = 13;

    if (f.y >= GROUND) {
      if (!wasGround) {
        if (f.vy > 3) {
          spawnDust(f.x, GROUND, 5, '#a697a7');
          if (f.isPlayer) audio.sfx('land');
        }
      }
      f.y = GROUND;
      f.vy = 0;
      f.onGround = true;
      if (f.state === 'jump') f.state = 'idle';
    } else {
      f.onGround = false;
    }

    f.vx *= drag;
    if (f.onGround && Math.abs(f.vx) < 0.03) f.vx = 0;
    f.x = clamp(f.x, 34, W - 34);
  }

  function startDash(f) {
    f.state = 'dash';
    f.stateTime = 0;
    f.dashTime = 9;
    f.dashCooldown = 48;
    f.vx = f.facing * 5.9;
    f.vy = 0;
    spawnDust(f.x - f.facing * 8, GROUND, 7, '#a697a7');
    if (f.isPlayer) audio.sfx('dash');
