      ctx.fillRect(Math.round(leaf.x + wob), Math.round(leaf.y), leaf.size, 1);
      ctx.fillRect(Math.round(leaf.x + wob) + 1, Math.round(leaf.y) + 1, Math.max(1, leaf.size - 1), 1);
