import { chromium } from '/home/runner/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/index.mjs';
const url = 'http://localhost:4173/index.html';
const errors = [];
const browser = await chromium.launch();

const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
await page.goto(url, { waitUntil: 'networkidle' });
await page.keyboard.press('Enter');
await page.waitForTimeout(3000);
console.log('desktop state', JSON.stringify(await page.evaluate(() => {
  const g = window.__LEMMY__;
  return { screen: g.game.screen, round: g.game.round, timer: Math.round(g.game.timer), pHealth: g.player.health, eHealth: g.enemy.health, pX: Math.round(g.player.x), eX: Math.round(g.enemy.x) };
})));
await page.screenshot({ path: '/tmp/opencode/v3-fight-desktop.png' });

await page.keyboard.down('KeyD');
await page.waitForTimeout(900);
await page.keyboard.up('KeyD');
await page.keyboard.press('KeyJ');
await page.waitForTimeout(120);
await page.screenshot({ path: '/tmp/opencode/v3-punch-desktop.png' });
await page.waitForTimeout(500);
console.log('after move/punch', JSON.stringify(await page.evaluate(() => {
  const g = window.__LEMMY__;
  return { pX: Math.round(g.player.x), pState: g.player.state, pHealth: g.player.health, eHealth: g.enemy.health, pCombo: g.game.playerCombo, meter: Math.round(g.player.meter) };
})));

await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/opencode/v3-fight2-desktop.png' });

const mob = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
mob.on('pageerror', e => errors.push('mobile pageerror: ' + e.message));
await mob.goto(url, { waitUntil: 'networkidle' });
await mob.tap('#startBtn');
await mob.waitForTimeout(3200);
console.log('mobile fight', JSON.stringify(await mob.evaluate(() => {
  const g = window.__LEMMY__;
  return { screen: g.game.screen, touchVisible: !document.getElementById('touchControls').classList.contains('is-hidden'), quickVisible: !document.getElementById('quickTools').classList.contains('is-hidden'), pX: Math.round(g.player.x), eX: Math.round(g.enemy.x) };
})));
await mob.screenshot({ path: '/tmp/opencode/v3-fight-mobile.png' });

const right = mob.locator('[data-act="right"]');
await right.dispatchEvent('pointerdown', { pointerId: 1, pointerType: 'touch', isPrimary: true });
await mob.waitForTimeout(800);
await right.dispatchEvent('pointerup', { pointerId: 1, pointerType: 'touch', isPrimary: true });
await mob.waitForTimeout(150);
console.log('mobile moved', JSON.stringify(await mob.evaluate(() => ({ pX: Math.round(window.__LEMMY__.player.x), state: window.__LEMMY__.player.state }))));
await mob.tap('[data-act="punch"]');
await mob.waitForTimeout(180);
await mob.screenshot({ path: '/tmp/opencode/v3-punch-mobile.png' });
await mob.waitForTimeout(500);
console.log('mobile punch', JSON.stringify(await mob.evaluate(() => ({ eHealth: window.__LEMMY__.enemy.health, pCombo: window.__LEMMY__.game.playerCombo }))));

const land = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await land.goto(url, { waitUntil: 'networkidle' });
await land.tap('#startBtn');
await land.waitForTimeout(3200);
await land.screenshot({ path: '/tmp/opencode/v3-fight-landscape.png' });
console.log('landscape', JSON.stringify(await land.evaluate(() => ({
  screen: window.__LEMMY__.game.screen,
  touchVisible: !document.getElementById('touchControls').classList.contains('is-hidden'),
  scrollW: document.documentElement.scrollWidth, innerW: innerWidth,
  scrollH: document.documentElement.scrollHeight, innerH: innerHeight,
  frame: (() => { const r = document.getElementById('gameFrame').getBoundingClientRect(); return [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)]; })(),
}))));

console.log('ERRORS', JSON.stringify(errors));
await browser.close();

