import { chromium } from '/home/runner/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/index.mjs';
const url = 'http://localhost:4173/index.html';
const browser = await chromium.launch();
const errors = [];

async function shot(viewport, opts, name, action) {
  const page = await browser.newPage({ viewport, ...opts });
  page.on('pageerror', e => errors.push(name + ': ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(name + ': ' + m.text()); });
  await page.goto(url, { waitUntil: 'networkidle' });
  await page.waitForTimeout(600);
  if (action) await action(page);
  await page.screenshot({ path: `/tmp/opencode/${name}.png` });
  const m = await page.evaluate(() => {
    const frame = document.getElementById('gameFrame').getBoundingClientRect();
    const deck = document.querySelector('.portrait-deck').getBoundingClientRect();
    return {
      scrollW: document.documentElement.scrollWidth, innerW: innerWidth,
      scrollH: document.documentElement.scrollHeight, innerH: innerHeight,
      frame: [Math.round(frame.x), Math.round(frame.y), Math.round(frame.width), Math.round(frame.height)],
      deck: [Math.round(deck.x), Math.round(deck.y), Math.round(deck.width), Math.round(deck.height)],
      deckDisplay: getComputedStyle(document.querySelector('.portrait-deck')).display,
      touch: !document.getElementById('touchControls').classList.contains('is-hidden'),
      screen: window.__LEMMY__.game.screen,
    };
  });
  console.log(name, JSON.stringify(m));
  await page.close();
}

const mobile = { isMobile: true, hasTouch: true, deviceScaleFactor: 2 };
await shot({ width: 390, height: 844 }, mobile, 'v4-title-mobile');
await shot({ width: 390, height: 844 }, mobile, 'v4-fight-mobile', async (p) => {
  await p.tap('#startBtn');
  await p.waitForTimeout(3200);
});
await shot({ width: 375, height: 667 }, mobile, 'v4-fight-se', async (p) => {
  await p.tap('#startBtn');
  await p.waitForTimeout(3200);
});
await shot({ width: 844, height: 390 }, mobile, 'v4-fight-landscape', async (p) => {
  await p.tap('#startBtn');
  await p.waitForTimeout(3200);
});
await shot({ width: 1280, height: 800 }, {}, 'v4-fight-desktop', async (p) => {
  await p.keyboard.press('Enter');
  await p.waitForTimeout(3200);
});
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

