import { chromium } from '/home/runner/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:4173/index.html', { waitUntil: 'networkidle' });
await page.keyboard.press('Enter');
await page.waitForTimeout(3000);
const s = () => page.evaluate(() => {
  const g = window.__LEMMY__;
  return { screen: g.game.screen, round: g.game.round, pw: g.game.playerWins, ew: g.game.enemyWins, result: g.game.showResult, paused: g.game.paused, pHealth: g.player.health, eHealth: g.enemy.health };
});
console.log('round1 fight', JSON.stringify(await s()));

// Fury test: full meter
await page.evaluate(() => { window.__LEMMY__.player.meter = 100; window.__LEMMY__.player.x = 380; window.__LEMMY__.enemy.x = 420; });
await page.keyboard.press('KeyU');
await page.waitForTimeout(250);
await page.screenshot({ path: '/tmp/opencode/v4-special.png' });
await page.waitForTimeout(900);
console.log('after fury', JSON.stringify(await page.evaluate(() => ({ state: window.__LEMMY__.player.state, meter: Math.round(window.__LEMMY__.player.meter), eHealth: window.__LEMMY__.enemy.health, combo: window.__LEMMY__.game.stats.maxCombo }))));

// finish round 1
await page.evaluate(() => { window.__LEMMY__.game.koSide = 'enemy'; });
await page.waitForTimeout(3900);
console.log('after r1 KO', JSON.stringify(await s()));
await page.waitForTimeout(2600);
console.log('r2 fight', JSON.stringify(await s()));
await page.screenshot({ path: '/tmp/opencode/v4-round2.png' });

// finish round 2 -> match end
await page.evaluate(() => { window.__LEMMY__.game.koSide = 'enemy'; });
await page.waitForTimeout(5200);
console.log('match end', JSON.stringify(await s()));
await page.screenshot({ path: '/tmp/opencode/v4-result.png' });
const resultVisible = await page.evaluate(() => !document.getElementById('resultScreen').classList.contains('is-hidden'));
console.log('resultVisible', resultVisible);

// rematch
await page.click('#rematchBtn');
await page.waitForTimeout(500);
console.log('rematch', JSON.stringify(await s()));

// pause via topbar, resume, quit
await page.click('#pauseBtn');
await page.waitForTimeout(200);
console.log('paused', JSON.stringify(await s()));
await page.screenshot({ path: '/tmp/opencode/v4-pause.png' });
await page.click('#resumeBtn');
await page.waitForTimeout(200);
await page.click('#pauseBtn');
await page.click('#quitBtn');
await page.waitForTimeout(300);
console.log('quit', JSON.stringify(await s()));
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

