import { chromium } from '/home/runner/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:4173/index.html', { waitUntil: 'networkidle' });
await page.tap('#startBtn');
await page.waitForTimeout(3000);

const setup = async () => page.evaluate(() => {
  const g = window.__LEMMY__;
  g.player.x = 380; g.enemy.x = 420; g.enemy.ai.cooldown = 999; g.enemy.ai.think = 999;
  g.player.facing = 1; g.enemy.facing = -1;
});
await setup();
await page.tap('[data-act="punch"]');
await page.waitForTimeout(250);
console.log('touch punch', JSON.stringify(await page.evaluate(() => ({ eHealth: window.__LEMMY__.enemy.health, pState: window.__LEMMY__.player.state, combo: window.__LEMMY__.game.stats.maxCombo }))));
await page.waitForTimeout(700);

await setup();
await page.tap('[data-act="kick"]');
await page.waitForTimeout(400);
console.log('touch kick', JSON.stringify(await page.evaluate(() => ({ eHealth: window.__LEMMY__.enemy.health, pState: window.__LEMMY__.player.state }))));
await page.waitForTimeout(800);

await setup();
await page.evaluate(() => { window.__LEMMY__.player.meter = 100; });
await page.tap('[data-act="special"]');
await page.waitForTimeout(1100);
console.log('touch fury', JSON.stringify(await page.evaluate(() => ({ eHealth: window.__LEMMY__.enemy.health, pState: window.__LEMMY__.player.state, meter: Math.round(window.__LEMMY__.player.meter) }))));

await page.waitForTimeout(1200);
await setup();
const guard = page.locator('[data-act="guard"]');
const before = await page.evaluate(() => window.__LEMMY__.input.guard);
await guard.dispatchEvent('pointerdown', { pointerId: 3, pointerType: 'touch', isPrimary: true });
await page.waitForTimeout(250);
const during = await page.evaluate(() => ({ guard: window.__LEMMY__.input.guard, state: window.__LEMMY__.player.state, cls: document.querySelector('[data-act="guard"]').className }));
await guard.dispatchEvent('pointerup', { pointerId: 3, pointerType: 'touch', isPrimary: true });
await page.waitForTimeout(150);
const after = await page.evaluate(() => ({ guard: window.__LEMMY__.input.guard, state: window.__LEMMY__.player.state }));
console.log('guard', JSON.stringify({ before, during, after }));

const jump = page.locator('[data-act="jump"]');
await jump.dispatchEvent('pointerdown', { pointerId: 4, pointerType: 'touch', isPrimary: true });
await page.waitForTimeout(200);
const jumped = await page.evaluate(() => ({ y: Math.round(window.__LEMMY__.player.y), onGround: window.__LEMMY__.player.onGround, state: window.__LEMMY__.player.state }));
await jump.dispatchEvent('pointerup', { pointerId: 4, pointerType: 'touch', isPrimary: true });
console.log('jump', JSON.stringify(jumped));

// quick pause and mute
await page.tap('#quickPause');
await page.waitForTimeout(250);
console.log('quick pause', JSON.stringify(await page.evaluate(() => ({ paused: window.__LEMMY__.game.paused, visible: !document.getElementById('pauseScreen').classList.contains('is-hidden') }))));
await page.screenshot({ path: '/tmp/opencode/v4-pause-mobile.png' });
await page.tap('#quickPause');
await page.waitForTimeout(200);
await page.tap('#quickMute');
await page.waitForTimeout(150);
console.log('quick mute', JSON.stringify(await page.evaluate(() => ({ text: document.getElementById('quickMute').textContent }))));
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

